function btn(text,act,ico='',cls='',attrs=''){return `<button class="${cls}" data-action="${act}" ${attrs}>${ico?icon(ico):''}${esc(text)}</button>`}
function badge(t){return `<span class="badge ${['Pago','Recebido','Concluído','Ativo','Livre'].includes(t)?'ok':['Cancelado','Arquivado','Estoque baixo'].includes(t)?'bad':'warn'}">${esc(t)}</span>`}
function empty(title='Nenhum registro encontrado',desc='Comece adicionando seu primeiro registro.',act='',label='Adicionar'){return `<div class="empty">${icon('box')}<h3>${esc(title)}</h3><p>${esc(desc)}</p>${act?btn(label,act,'plus','primary'):''}</div>`}
function stat(label,value,detail='',cls=''){return `<div class="stat"><small>${esc(label)}</small><b class="${cls}">${esc(value)}</b>${detail?`<em>${esc(detail)}</em>`:''}</div>`}
function table(headers,rows){return rows.length?`<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c??''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('Nenhum registro encontrado','Não há dados para os filtros selecionados.');}
function pageHead(actions=''){return `<div class="pagehead"><div><h1>${esc(route==='home'?'Olá, '+(S.settings.name||'Tiago'):titles[route]||'Lojinha')}</h1><div class="crumb"><a href="#home">Início</a>${route!=='home'?' &nbsp;·&nbsp; '+esc(titles[route]||''):''}</div></div><div class="actions">${actions}</div></div>`}
function toolbar(extra=''){return `<div class="toolbar"><label class="search">${icon('search')}<input type="search" id="search" placeholder="Buscar por nome, código ou observação" aria-label="Buscar" value="${esc(search)}"></label><div class="actions">${extra}${btn('Exportar CSV','export','download')}${btn('Imprimir / PDF','print','print')}</div></div>`}
function filterRows(rows){return rows.filter(x=>!search||JSON.stringify(x).toLowerCase().includes(search.toLowerCase()));}
function dated(rows){return rows.filter(x=>(!dateFrom||(x.date||x.createdAt?.slice(0,10))>=dateFrom)&&(!dateTo||(x.date||x.createdAt?.slice(0,10))<=dateTo));}
