function categoryLabel(id){const category=find('financialCategories',id);if(!category)return 'Sem categoria';const parent=find('financialCategories',category.parentId);return parent?parent.name+' / '+category.name:category.name;}
function expenseRoots(){const order=['Despesas operacionais','Compras'];return R('financialCategories').filter(c=>!c.parentId&&c.type!=='Entrada').sort((a,b)=>{const ai=order.indexOf(a.name),bi=order.indexOf(b.name);return (ai<0?99:ai)-(bi<0?99:bi)||a.name.localeCompare(b.name,'pt-BR');});}
