function cashPage(){const active=R('cash').find(c=>c.status==='Aberto'),closed=dated(R('cash').filter(c=>c.status==='Fechado'));return `<div class="callout"><div><strong>Conferência do turno</strong><p>O Financeiro registra o extrato completo. O caixa confere o dinheiro da gaveta, incluindo vendas e lançamentos em espécie feitos após a abertura.</p></div></div>${active?`<section class="panel"><div class="row wrap"><h2>${esc(active.name)}</h2>${badge('Aberto')}</div><div class="stats">${stat('Troco inicial',money(active.opening))}${stat('Saldo esperado',money(active.expected))}${stat('Aberto em',datefmt(active.openedAt))}</div><div class="actions">${btn('Suprimento','entry:Entrada','plus')}${btn('Sangria','entry:Despesa','wallet')}${btn('Fechar caixa','closecash:'+active.id,'check','success')}</div></section>`:empty('Nenhum caixa aberto','Informe o dinheiro disponível na gaveta para iniciar o turno.','opencash','Abrir caixa')}<section class="panel"><h2>Fechamentos</h2>${dates()}<div class="mt">${table(['Caixa','Abertura','Fechamento','Esperado','Contado','Diferença'],closed.map(c=>[esc(c.name),datefmt(c.openedAt),datefmt(c.closedAt),money(c.expected),money(c.counted),`<b class="${c.difference<0?'negative':'positive'}">${money(c.difference)}</b>`]))}</div></section>`;}
function purchasesPage(){return `${toolbar()}${table(['Fornecedor','Data','Total','Status','Ações'],dated(filterRows(R('purchases'))).map(p=>[esc(name('suppliers',p.supplierId)),datefmt(p.date),money(p.total),badge(p.status),btn('Abrir','purchasedetail:'+p.id,'file','small')+(p.status==='Pendente'?btn('Receber estoque','receivepurchase:'+p.id,'check','small')+btn('Cancelar','cancelpurchase:'+p.id,'close','small'):'')]))}`;}
function purchaseForm(){if(!R('suppliers').length){toast('Cadastre um fornecedor primeiro.');nav('suppliers');return;}if(!R('products').length){toast('Cadastre produtos primeiro.');nav('products');return;}const fields=[F('supplierId','Fornecedor','ref',{ref:'suppliers',required:true}),F('date','Data','date',{required:true}),F('notes','Observação','textarea',{wide:true})];showModal('Novo pedido ao fornecedor',`<form id="purchaseform"><div class="formgrid">${fields.map(f=>fieldHTML(f,{date:today()})).join('')}</div><h3 class="mt">Produtos</h3><div id="purchaseitems"></div>${btn('Adicionar produto','purchaseadd','plus')}<p class="formerror"></p><div class="formfoot"><button type="submit" class="primary">Salvar pedido</button></div></form>`);purchaseAdd();$('#purchaseform').onsubmit=async e=>{e.preventDefault();let button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;try{const data=await readFields(e.currentTarget,fields);data.items=[...$('#purchaseitems').children].map(row=>({productId:row.querySelector('[name=product]').value,variant:row.querySelector('[name=variant]').value,qty:Number(row.querySelector('[name=quantity]').value),cost:Number(row.querySelector('[name=cost]').value)}));await api('purchases',data);closeModal();await load();render();toast('Pedido criado.')}catch(err){$('#purchaseform .formerror').textContent=err.message}finally{button.disabled=false}};}
function purchaseAdd(){const div=document.createElement('div');div.className='panel';div.innerHTML=`<div class="formgrid"><label class="field"><span>Produto</span><select name="product">${R('products').map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label class="field"><span>Variação</span><select name="variant"></select></label><label class="field"><span>Quantidade</span><input type="number" name="quantity" min="0.000001" step="any" value="1" required></label><label class="field"><span>Custo unitário (R$)</span><input type="number" name="cost" min="0" step="0.01" required></label></div><button type="button" class="small danger mt" data-action="removepurchaserow">Remover</button>`;$('#purchaseitems').append(div);const update=()=>{const p=find('products',div.querySelector('[name=product]').value);div.querySelector('[name=cost]').value=p.cost;div.querySelector('[name=variant]').innerHTML=(p.variants?.length?p.variants:[{name:''}]).map(v=>`<option>${esc(v.name)}</option>`).join('')};div.querySelector('[name=product]').onchange=update;update();}
function aggregate(rows,key,value){const map=new Map();for(const row of rows){const k=key(row)||'Não informado';map.set(k,(map.get(k)||0)+value(row))}return [...map].sort((a,b)=>b[1]-a[1]);}
function sales(){return dated(R('orders').filter(o=>!o.quote&&o.status!=='Cancelado'));}
function bars(items,isMoney=true){const max=Math.max(...items.map(x=>x[1]),1);return items.length?`<div class="barlist">${items.slice(0,8).map(([label,v])=>`<div class="baritem"><div class="row"><span>${esc(label)}</span><b>${isMoney?money(v):qty(v)}</b></div><div class="bartrack"><div style="width:${Math.max(1,v/max*100)}%"></div></div></div>`).join('')}</div>`:empty('Nenhum dado no período','As vendas aparecerão aqui.');}
function dashboard(){const orders=sales(),total=orders.reduce((a,o)=>a+o.total,0),cost=orders.reduce((a,o)=>a+o.cost,0),evolution=aggregate(orders,o=>o.date,o=>o.total).sort((a,b)=>a[0].localeCompare(b[0])).slice(-30),max=Math.max(...evolution.map(x=>x[1]),1),products=aggregate(orders.flatMap(o=>o.items),i=>i.name,i=>i.qty),methods=aggregate(dated(validEntries().filter(e=>e.paid&&e.type==='Entrada'&&e.orderId)),e=>e.methodName,e=>e.value);return `<div class="panel"><div class="toolbar">${dates()}<div class="chips">${btn('Hoje','period:0')}${btn('7 dias','period:7')}${btn('30 dias','period:30')}${btn('Todo o período','period:all')}</div></div></div><div class="stats">${stat('Vendas',money(total),orders.length+' pedido(s)')}${stat('Ticket médio',money(orders.length?total/orders.length:0))}${stat('Margem bruta',money(total-cost),'Antes de taxas de operadoras e despesas')}${stat('Recebido',money(orders.reduce((a,o)=>a+o.paid,0)))}</div><section class="panel"><div class="toolbar"><h2>Evolução de vendas</h2><a href="#report-summary" class="subtitle">Ver resumo completo →</a></div>${evolution.length?`<div class="chart">${evolution.map(([d,v])=>`<div class="chartcol" title="${datefmt(d)}: ${money(v)}"><div class="chartbar" style="height:${v/max*100}%"></div><small>${esc(d.slice(8)+'/'+d.slice(5,7))}</small></div>`).join('')}</div>`:empty('Nenhum dado no período','Registre vendas para acompanhar a evolução.')}</section><div class="grid2"><section class="panel"><h2>Produtos mais vendidos</h2>${bars(products,false)}</section><section class="panel"><h2>Vendas por forma de pagamento</h2>${bars(methods)}</section><section class="panel"><h2>Melhores clientes</h2>${bars(aggregate(orders,o=>name('clients',o.clientId),o=>o.total))}</section><section class="panel"><h2>Resumo por vendedor</h2>${bars(aggregate(orders,o=>name('users',o.sellerId),o=>o.total))}</section></div>`;}
function reportData(type){let orders=sales(),entries=dated(validEntries()),heads=[],rows=[];
if(['orders','debts'].includes(type)){heads=['Pedido','Data','Cliente','Vendedor','Status','Custo','Total','Recebido','Pendente'];rows=orders.filter(o=>type!=='debts'||o.paid<o.total).map(o=>['#'+o.number,datefmt(o.date),name('clients',o.clientId),name('users',o.sellerId),o.status,money(o.cost),money(o.total),money(o.paid),money(o.total-o.paid)])}
else if(type==='stock'){heads=['Produto','Código','Categoria','Estoque','Mínimo','Custo em estoque','Venda em estoque'];rows=R('products').filter(p=>p.trackStock&&p.type!=='Serviço').map(p=>[p.name,p.barcode||'',name('categories',p.categoryId),qty(p.stock),qty(p.minStock),money(Math.round(p.stock*p.cost*100)),money(Math.round(p.stock*p.price*100))])}
else if(type==='movements'){heads=['Data','Produto','Variação','Movimento','Saldo','Motivo'];rows=dated(R('movements')).map(m=>[datefmt(m.date),m.name,m.variant||'',qty(m.delta),qty(m.balance),m.reason])}
else if(type==='financial'){heads=['Data','Lançamento','Categoria','Tipo','Pagamento','Valor','Situação'];rows=entries.map(e=>[datefmt(e.date),e.name,categoryLabel(e.categoryId),e.type,e.methodName||'',money(e.value),e.paid?'Pago':'Pendente'])}
else if(type==='methods'){heads=['Forma de pagamento','Entradas recebidas','Despesas pagas','Saldo','Taxas estimadas'];const methods=[...new Set(entries.filter(e=>e.paid).map(e=>e.methodName||'Não informado'))];rows=methods.map(m=>{const group=entries.filter(e=>e.paid&&(e.methodName||'Não informado')===m),income=group.filter(e=>e.type==='Entrada').reduce((a,e)=>a+e.value,0),expense=group.filter(e=>e.type==='Despesa').reduce((a,e)=>a+e.value,0);return [m,money(income),money(expense),money(income-expense),money(group.reduce((a,e)=>a+(e.fee||0),0))]})}
else if(type==='products'){heads=['Produto','Quantidade','Custo','Vendas'];const grouped=aggregate(orders.flatMap(o=>o.items),i=>i.name,i=>i.qty);rows=grouped.map(([n,q])=>{const items=orders.flatMap(o=>o.items).filter(i=>i.name===n);return [n,qty(q),money(items.reduce((a,i)=>a+Math.round(i.cost*i.qty),0)),money(items.reduce((a,i)=>a+Math.round(i.price*i.qty),0))]})}
else if(['clients','sellers','coupons'].includes(type)){const key=type==='clients'?'clientId':type==='sellers'?'sellerId':'coupon',entity=type==='clients'?'clients':'users';heads=[type==='clients'?'Cliente':type==='sellers'?'Vendedor':'Cupom','Pedidos','Total',...(type==='sellers'?['Comissão estimada']:[])];const grouped=aggregate(orders.filter(o=>type!=='coupons'||o.coupon),o=>o[key]||'Não informado',o=>o.total);rows=grouped.map(([id,total])=>[type==='coupons'?id:name(entity,id),orders.filter(o=>(o[key]||'Não informado')===id).length,money(total),...(type==='sellers'?[money(Math.round(total*(find('users',id)?.commission||0)/100))]:[])])}
else {heads=['Data','Pedidos','Total','Custos','Margem bruta'];const grouped=aggregate(orders,o=>o.date,o=>o.total);rows=grouped.map(([d,total])=>{const group=orders.filter(o=>o.date===d),cost=group.reduce((a,o)=>a+o.cost,0);return [datefmt(d),group.length,money(total),money(cost),money(total-cost)]})}
return {heads,rows:rows.filter(r=>!search||r.join(' ').toLowerCase().includes(search.toLowerCase()))};}
function reportPage(){const type=route.replace('report-',''),report=reportData(type);return `<div class="panel">${dates()}${['stock'].includes(type)?'<p class="filehint">O estoque mostra a posição atual; as datas não alteram o saldo.</p>':''}</div>${toolbar()}${table(report.heads,report.rows.map(r=>r.map(esc)))}`;}
