function settingsPage(){return `<p class="subtitle">${route==='printers'?'A impressão usa a impressora configurada no Windows. Escolha “Salvar como PDF” na janela de impressão para gerar um arquivo.':route==='store'?'O catálogo fica disponível neste computador. Para disponibilizar aos seus clientes pela internet, será necessário hospedar a aplicação.':''}</p><section class="panel"><form id="settingsform"><div class="formgrid">${settingSchemas[route].map(f=>fieldHTML(f,S.settings)).join('')}</div>${route==='settings'?'<div id="brandpreview" class="brandpreview"></div><p id="brandstatus" class="filehint" role="status"></p><button type="button" id="extractcolors" class="small">Usar cores da logo</button>':''}<p class="formerror" role="alert"></p><div class="formfoot"><button class="primary" type="submit">Salvar alterações</button></div></form></section>${route==='settings'?`<div class="settingsnav">${menu.find(g=>g[0]==='CONFIGURAÇÕES')[1].filter(([id])=>id!=='settings').map(([id,t,i])=>`<a href="#${id}">${icon(i)} ${esc(t)}</a>`).join('')}</div>`:''}`;}
function settingsBind(){
const form=$('#settingsform');if(!form)return;
let draftLogo=S.settings.logo||'',lastPaletteLogo='',palettePromise=null;
const preview=()=>{const box=$('#brandpreview');if(!box)return;const primary=validColor(form.elements.brandPrimary?.value||S.settings.brandPrimary),secondary=validColor(form.elements.brandSecondary?.value||S.settings.brandSecondary,'#2563eb'),company=form.elements.company?.value||S.settings.company||'Minha loja',removed=form.elements.removeLogo?.checked;box.innerHTML=`<small>PRÉVIA DA SUA MARCA</small><div class="brandpreview-row">${draftLogo&&!removed?`<img src="${esc(safeImage(draftLogo))}" alt="Prévia da logo">`:`<span class="brandpreview-initial" style="background:${primary};color:${readableInk(primary)}">${esc(company[0]||'L')}</span>`}<strong>${esc(company)}</strong></div><div class="brandpreview-palette"><span style="background:${primary};color:${readableInk(primary)}">Cor principal</span><span style="background:${secondary};color:${readableInk(secondary)}">Cor de destaque</span></div>`;};
const suggest=async()=>{if(!draftLogo)throw Error('Selecione a logo da loja primeiro.');const palette=await extractLogoPalette(draftLogo);if(form.elements.autoLogoColors&&!form.elements.autoLogoColors.checked)return palette;if(form.elements.brandPrimary)form.elements.brandPrimary.value=palette.primary;if(form.elements.brandSecondary)form.elements.brandSecondary.value=palette.secondary;if(form.elements.catalogColor)form.elements.catalogColor.value=palette.primary;lastPaletteLogo=draftLogo;form.dataset.palettePrimary=palette.primary;form.dataset.paletteSecondary=palette.secondary;preview();if($('#brandstatus'))$('#brandstatus').textContent='Cores sugeridas a partir da logo. Você pode ajustá-las antes de salvar.';return palette;};
const runSuggestion=()=>{palettePromise=suggest().catch(err=>{form.querySelector('.formerror').textContent=err.message;throw err;});palettePromise.catch(()=>{});return palettePromise;};
if(form.elements.logo)form.elements.logo.addEventListener('change',async()=>{try{const file=form.elements.logo.files[0];if(!file)return;if(file.size>2_000_000||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Use PNG, JPG ou WebP de até 2 MB.');draftLogo=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=()=>reject(Error('Não foi possível ler a logo.'));fr.readAsDataURL(file)});if(form.elements.removeLogo)form.elements.removeLogo.checked=false;preview();if(form.elements.autoLogoColors?.checked??S.settings.autoLogoColors!==false)await runSuggestion();}catch(err){form.querySelector('.formerror').textContent=err.message;}});
if(form.elements.company)form.elements.company.addEventListener('input',preview);
if(form.elements.removeLogo)form.elements.removeLogo.addEventListener('change',preview);
for(const key of ['brandPrimary','brandSecondary'])if(form.elements[key])form.elements[key].addEventListener('input',()=>{if(form.elements.autoLogoColors)form.elements.autoLogoColors.checked=false;preview();});
if(form.elements.autoLogoColors)form.elements.autoLogoColors.addEventListener('change',()=>{if(form.elements.autoLogoColors.checked&&draftLogo)runSuggestion();});
if($('#extractcolors'))$('#extractcolors').onclick=()=>{if(form.elements.autoLogoColors)form.elements.autoLogoColors.checked=true;runSuggestion();};
preview();
form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]');b.disabled=true;try{
if(palettePromise&&(form.elements.autoLogoColors?.checked??S.settings.autoLogoColors!==false))await palettePromise;const data=await readFields(form,settingSchemas[route],S.settings);
if(data.removeLogo)data.logo='';delete data.removeLogo;
const auto=data.autoLogoColors??S.settings.autoLogoColors!==false;
if(data.logo&&auto&&(data.logo!==S.settings.logo||route==='settings')){const palette=lastPaletteLogo===data.logo?{primary:form.dataset.palettePrimary,secondary:form.dataset.paletteSecondary}:await extractLogoPalette(data.logo);data.brandPrimary=palette.primary;data.brandSecondary=palette.secondary;data.catalogColor=palette.primary;}
if(route==='settings'&&data.brandPrimary)data.catalogColor=data.brandPrimary;
await api('settings',data);await load();render();toast('Configurações salvas.');
}catch(err){form.querySelector('.formerror').textContent=err.message}finally{b.disabled=false}};
}
function tablesPage(){const mode=S.settings.tableMode||'none',orders=R('orders').filter(o=>!o.quote&&!['Concluído','Cancelado'].includes(o.status));return `<div class="panel"><h2>Como você atende?</h2><p class="subtitle">Cada mesa ou comanda pode ter um pedido aberto, com fechamento e pagamento ao final do atendimento.</p><div class="chips">${[['none','Não uso'],['table','Por mesa'],['tab','Por comanda']].map(([v,t])=>btn(t,'tablemode:'+v,'table',mode===v?'active':'')).join('')}</div></div>${mode==='none'?empty('Mesas e comandas desativadas','Escolha um modo de atendimento acima para começar.'):`<div class="productgrid">${R('tables').map(t=>{const o=orders.find(o=>o.tableId===t.id);return `<div class="tabletile ${o?'occupied':''}">${icon('table')}<h3>${esc(t.name)}</h3>${badge(o?'Ocupada':'Livre')}<p>${o?money(o.total):'Sem pedido aberto'}</p>${btn(o?'Abrir pedido':'Iniciar atendimento',o?'orderdetail:'+o.id:'tableorder:'+t.id,'sale','small')}${entityActions('tables',t.id)}</div>`}).join('')}</div>${!R('tables').length?empty('Nenhuma mesa ou comanda cadastrada','Adicione as mesas ou cartões que você utiliza.','new:tables','Adicionar'):''}`}`;}
let labelSelection={},labelPrice=true,labelBarcode=true,labelColumns=3;
function labelsPage(){return `<div class="grid2"><section class="panel"><h2>Selecionar produtos</h2>${toolbar()}${R('products').filter(p=>!search||p.name.toLowerCase().includes(search.toLowerCase())).map(p=>`<div class="row" style="justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--line)"><span>${esc(p.name)}<br><small class="muted">${esc(p.barcode||'Sem código')}</small></span>${btn('Selecionar','labeladd:'+p.id,'plus','small')}</div>`).join('')||empty('Nenhum produto','Cadastre produtos para imprimir etiquetas.')}</section><section class="panel"><h2>Selecionados</h2>${Object.entries(labelSelection).map(([id,q])=>`<label class="field"><span>${esc(name('products',id))}</span><input type="number" min="0" max="300" step="1" data-labelqty="${id}" value="${q}"></label>`).join('')||'<p class="subtitle">Nenhum produto selecionado.</p>'}<div class="splitline"></div>${fieldHTML(F('labelPrice','Incluir preço','checkbox'),{labelPrice})}${fieldHTML(F('labelBarcode','Incluir código de barras','checkbox'),{labelBarcode})}${fieldHTML(F('labelColumns','Colunas por página','select',{options:[['3','3 colunas (27 etiquetas)'],['2','2 colunas'],['4','4 colunas']]}),{labelColumns})}${btn('Pré-visualizar etiquetas','labelpreview','print','primary mt')}</section></div>`;}
// Code 128 subset B: each symbol is encoded using its standard six-width pattern.
const code128=['212222','222122','222221','121223','121322','131222','122213','122312','132212','221213','221312','231212','112232','122132','122231','113222','123122','123221','223211','221132','221231','213212','223112','312131','311222','321122','321221','312212','322112','322211','212123','212321','232121','111323','131123','131321','112313','132113','132311','211313','231113','231311','112133','112331','132131','113123','113321','133121','313121','211331','231131','213113','213311','213131','311123','311321','331121','312113','312311','332111','314111','221411','431111','111224','111422','121124','121421','141122','141221','112214','112412','122114','122411','142112','142211','241211','221114','413111','241112','134111','111242','121142','121241','114212','124112','124211','411212','421112','421211','212141','214121','412121','111143','111341','131141','114113','114311','411113','411311','113141','114131','311141','411131','211412','211214','211232','2331112'];
function barcode(text){if(!/^[\x20-\x7e]{1,40}$/.test(text))return `<small>${esc(text||'Sem código de barras')}</small>`;const values=[104,...[...text].map(c=>c.charCodeAt(0)-32)],check=(104+values.slice(1).reduce((a,n,i)=>a+n*(i+1),0))%103;values.push(check,106);let x=10,rects='';for(const v of values)for(const [i,w]of [...code128[v]].entries()){if(i%2===0)rects+=`<rect x="${x}" y="0" width="${w}" height="30"/>`;x+=Number(w)}return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${x+10} 45" style="width:100%;height:45px" role="img" aria-label="Código de barras ${esc(text)}"><rect width="${x+10}" height="45" fill="white"/><g fill="black">${rects}</g><text x="${(x+10)/2}" y="42" text-anchor="middle" font-size="9" fill="black" font-family="monospace">${esc(text)}</text></svg>`;}
function labelsHTML(){let count=0;const out=[];for(const [id,q]of Object.entries(labelSelection)){const p=find('products',id);if(!p)continue;for(let i=0;i<q;i++){if(++count>300)throw Error('Imprima até 300 etiquetas por vez.');out.push(`<div class="labelprint"><strong>${esc(p.name)}</strong>${labelPrice?`<b>${money(Math.round(productPrice(p,1)*100))}</b>`:''}${labelBarcode?barcode(p.barcode||''):''}</div>`)}}if(!out.length)throw Error('Selecione pelo menos um produto.');return `<div class="labels" style="grid-template-columns:repeat(${labelColumns},1fr)">${out.join('')}</div>`;}
function catalogPage(pdf=false){if(!S.settings.catalogActive&&!pdf)return empty('Catálogo desativado','Ative o catálogo nas configurações da loja.');let products=filterRows(R('products').filter(p=>p.visible!==false)).filter(p=>S.settings.stockPolicy!=='hide'||p.type==='Serviço'||!p.trackStock||p.stock>p.reserved);return `<div class="catalogview" style="--accent:${/^#[0-9a-f]{6}$/i.test(S.settings.catalogColor)?S.settings.catalogColor:'#ed3127'}"><div class="catalogheader">${S.settings.logo&&S.settings.showLogo!==false?`<img src="${esc(safeImage(S.settings.logo))}" style="height:65px" alt="Logo">`:''}<h2>${esc(S.settings.company)}</h2><p class="subtitle">${esc(S.settings.catalogMessage||'Conheça nossos produtos e serviços.')}</p>${S.settings.openingHours?`<p class="filehint">${esc(S.settings.openingHours)}</p>`:''}${S.settings.showAddressCatalog!==false?`<p class="filehint">${esc([S.settings.address,S.settings.number,S.settings.city].filter(Boolean).join(', '))}</p>`:''}</div>${R('banners').filter(b=>b.active&&b.photo).sort((a,b)=>a.position-b.position).map(b=>`<img class="catalogbanner" src="${esc(safeImage(b.photo))}" alt="${esc(b.name)}">`).join('')}${toolbar(pdf?'':btn('Finalizar seleção','catalogcheckout','sale','primary'))}<div class="productgrid" style="${S.settings.catalogModel==='list'?'grid-template-columns:1fr':''}">${products.map(p=>pdf?`<div class="productcard">${productCard(p).replace(/^<button[^>]*>/,'').replace(/<\/button>$/,'')}<p class="subtitle" style="padding:0 12px">${esc(p.description)}</p></div>`:productCard(p,'catalogadd')).join('')}</div>${!products.length?empty('Nenhum produto no catálogo','Marque os produtos que deseja exibir ao cadastrá-los.'):''}</div>`;}
function integrationsPage(){return `<p class="subtitle">A aplicação local funciona sem acessar sua conta Kontro. Os serviços abaixo exigem conexão própria com um fornecedor.</p>${table(['Serviço','Situação','O que falta'],[['NFC-e / NF-e / NFS-e',badge('Não conectado'),'Certificado A1, credenciamento fiscal e integração com um emissor.'],['Pix / Mercado Pago / InfinitePay',badge('Registro manual'),'Integração de cobrança, credenciais e confirmação de pagamento.'],['SuperFrete / Correios',badge('Frete manual'),'Credenciais e API de cotação e etiquetas.'],['WhatsApp',badge('Mensagem para copiar'),'Envio automático exige serviço de mensagens conectado.'],['Catálogo na internet',badge('Local'),'Hospedagem, domínio e controle de acesso.'],['Acesso por usuários',badge(S.auth?.enabled?'Login do responsável':'Uso local'),'Vendedores são cadastros de acompanhamento. A versão online tem acesso protegido para o responsável; permissões individuais de vendedores não estão implementadas.']])}<section class="panel mt"><h2>Escopo da reconstrução</h2><p class="subtitle">As telas e funções foram reconstruídas a partir da navegação autorizada na conta. Recursos PRO bloqueados, regras internas e integrações do Kontro não puderam ser inspecionados por completo. Consulte MAPA-DO-SISTEMA.md na pasta do projeto para a cobertura e as limitações.</p></section>`;}
function backupPage(){return `<section class="panel"><h2>Cópia dos seus dados</h2><p class="subtitle">Salve os cadastros, vendas, estoque, financeiro e configurações em um arquivo. As fotos dos produtos também estão incluídas.</p>${btn('Baixar cópia de segurança','backup-download','download','primary')}<div class="splitline"></div><h3>Restaurar cópia</h3><p class="subtitle">A restauração substitui os dados atuais por um backup desta aplicação. ${S.storage==='postgres'?'Uma cópia automática dos dados atuais ficará no histórico do banco online antes da substituição.':'Uma cópia automática dos dados atuais será guardada na pasta data/backups antes da substituição.'}</p><label class="field"><span>Arquivo de backup (.json)</span><input id="backupfile" type="file" accept=".json,application/json"></label>${btn('Restaurar arquivo selecionado','restore','archive','danger mt')} ${btn('Baixar cópia anterior à restauração','backup-previous','download','mt')}</section>`;}
function receiptHTML(o){const client=find('clients',o.clientId),items=table(['Item','Qtd.','Valor'],o.items.map(i=>[esc(i.name+(i.variant?' / '+i.variant:''))+(i.receiptNote?`<br><small>${esc(i.receiptNote)}</small>`:''),qty(i.qty),money(Math.round(i.price*i.qty))]));return `<div class="receipt" style="max-width:${S.settings.paper==='58'?'220':'300'}px">${S.settings.logo&&S.settings.showLogo!==false?`<div class="center"><img src="${esc(safeImage(S.settings.logo))}" style="max-height:60px" alt="Logo"></div>`:''}<h2>${esc(S.settings.company)}</h2><p class="center">${esc(S.settings.document||'')}<br>${esc(S.settings.phone||'')}${S.settings.showAddressReceipt!==false?'<br>'+esc([S.settings.address,S.settings.number,S.settings.city].filter(Boolean).join(', ')):''}</p><p class="center"><b>${o.quote?'ORÇAMENTO':'COMPROVANTE NÃO FISCAL'} #${o.number}</b><br>${datefmt(o.date)} · ${esc(o.status)}</p>${client?`<p>Cliente: ${esc(client.name)}<br>${esc(client.document||'')}</p>`:''}${items}<p>Subtotal: ${money(o.subtotal)}<br>Descontos: ${money(o.discount)}<br>Taxas: ${money(o.service)}<br>Entrega: ${money(o.delivery)}</p><div class="totalrow"><b>Total</b><b>${money(o.total)}</b></div><p>Recebido: ${money(o.paid)}<br>Saldo: ${money(o.total-o.paid)}</p>${o.notes?`<p>${esc(o.notes)}</p>`:''}${Object.entries(o.custom||{}).filter(([id])=>find('orderFields',id)?.print).map(([id,v])=>`<p>${esc(name('orderFields',id))}: ${esc(v)}</p>`).join('')}${Object.entries(client?.custom||{}).filter(([id])=>find('clientFields',id)?.print).map(([id,v])=>`<p>${esc(name('clientFields',id))}: ${esc(v)}</p>`).join('')}<p class="center">${esc(S.settings.receiptMessage||'')}</p>${S.settings.receiptSignature?'<br><p>_________________________<br>Assinatura da loja</p><br><p>_________________________<br>Assinatura do cliente</p>':''}</div>`;}
function printHTML(html,title='Lojinha'){const old=$('#printframe');if(old)old.remove();const frame=document.createElement('iframe');frame.id='printframe';frame.style.cssText='position:fixed;width:0;height:0;border:0';frame.srcdoc=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font:12px Arial;color:#111;margin:20px}h1{font-size:22px}h2{font-size:18px}table{border-collapse:collapse;width:100%;text-align:left}th,td{padding:9px;border-bottom:1px solid #ddd;font-size:11px}.tablewrap{overflow:visible}.subtitle,.filehint{color:#555}.no-print,button,.toolbar,.search{display:none!important}.receipt{margin:0 auto}.center{text-align:center}.totalrow{display:flex;justify-content:space-between;padding:12px 0}.labels{display:grid;gap:6px}.labelprint{padding:10px;border:1px dashed #aaa;text-align:center;break-inside:avoid;min-height:90px;font-size:10px}.labelprint strong{display:block}.productgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.productcard{border:1px solid #ddd;padding:12px;break-inside:avoid}.productphoto{height:100px;text-align:center}.productphoto img{max-width:100%;height:100%;object-fit:contain}.productphoto svg{width:50px}.productinfo strong,.productinfo small{display:block;margin:8px 0}.catalogheader{text-align:center}.catalogbanner{display:none}@page{margin:12mm}</style></head><body>${html}</body></html>`;frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print()};document.body.append(frame);}
function download(text,filename,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function exportCSV(){let headers,rows;if(route.startsWith('report-'))({heads:headers,rows}=reportData(route.slice(7)));else{let el=$('#content table');if(!el){toast('Não há uma tabela para exportar.');return}headers=[...el.querySelectorAll('thead th')].map(c=>c.textContent);rows=[...el.querySelectorAll('tbody tr')].map(tr=>[...tr.cells].map(c=>c.textContent.trim()));if(headers.at(-1)==='Ações'){headers.pop();rows=rows.map(r=>r.slice(0,-1));}}const cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('\ufeff'+[headers,...rows].map(r=>r.map(cell).join(';')).join('\r\n'),'lojinha-'+route+'-'+today()+'.csv','text/csv;charset=utf-8');}
function mainActions(){if(schemas[route]&&route!=='tables')return btn('Adicionar','new:'+route,'plus','primary');if(route==='stock')return btn('Cadastrar produto','new:products','plus','primary');if(route==='orders')return btn('Nova venda','navigate:order','plus','primary');if(route==='quotes')return btn('Novo orçamento','newquote','plus','primary');if(route==='financial')return btn('Entrada','entry:Entrada','plus','success')+btn('Despesa','entry:Despesa','wallet');if(route==='cash')return !R('cash').some(c=>c.status==='Aberto')?btn('Abrir caixa','opencash','cash','success'):'';if(route==='purchases')return btn('Novo pedido','newpurchase','plus','primary');if(route==='tables')return btn('Adicionar mesa/comanda','new:tables','plus','primary');if(route==='manual')return btn('Registrar venda rápida','manualcheckout','bolt','primary');return '';}
function render(){applyBranding(S.settings);let content;document.title=(titles[route]||'Início')+' · '+(S.settings.company||'Lojinha');if(route==='home')content=home();else if(schemas[route]&&route!=='tables')content=entityList(route);else if(settingSchemas[route])content=settingsPage();else if(route.startsWith('report-'))content=reportPage();else switch(route){case 'stock':content=stockPage();break;case 'order':content=salePage();break;case 'manual':content=`<div class="panel"><h2>Venda rápida</h2><p class="subtitle">Registre uma venda sem selecionar produtos. Informe título, valor, cliente e pagamento. Vendas rápidas geram registros financeiros e não movimentam estoque.</p>${btn('Registrar venda rápida','manualcheckout','bolt','primary')}</div>`;break;case 'orders':content=ordersPage();break;case 'quotes':content=ordersPage(true);break;case 'financial':content=financePage();break;case 'debts':content=financePage(true);break;case 'cash':content=cashPage();break;case 'purchases':content=purchasesPage();break;case 'tables':content=tablesPage();break;case 'dashboard':content=dashboard();break;case 'labels':content=labelsPage();break;case 'catalog':content=catalogPage();break;case 'catalog-pdf':content=catalogPage(true);break;case 'backup':content=backupPage();break;case 'integrations':content=integrationsPage();break;default:content=empty('Página não encontrada','Escolha uma opção no menu.');}shell(content,mainActions());settingsBind();}
async function refresh(msg){await load();render();if(msg)toast(msg)}
async function handleAction(action,el){const [act,a,b]=action.split(':');switch(act){
case 'menu':document.body.classList.toggle('menuopen');break;
case 'theme':await api('settings',{theme:S.settings.theme==='light'?'dark':'light'});await refresh();break;
case 'profile':nav('settings');break;
case 'logout':await api('auth/logout',{});location.replace('/login');break;
case 'navigate':nav(a);break;
case 'new':entityForm(a);break;
case 'edit':entityForm(a,b);break;
case 'archive':if(confirm('Arquivar este registro? O histórico será preservado.')){await api(a+'/'+b,{},'DELETE');await refresh('Registro arquivado.')}break;
case 'close-modal':closeModal();break;
case 'backup-previous':{const response=await fetch('/api/backup/previous');if(response.status===401){location.replace('/login');break;}if(!response.ok)throw Error((await response.json()).error||'Não foi possível baixar a cópia anterior.');download(await response.text(),'lojinha-antes-da-restauracao.json','application/json');break;}
case 'backup-download':{const response=await fetch('/api/backup');if(!response.ok)throw Error('Não foi possível gerar o backup.');download(await response.text(),'lojinha-backup-'+today()+'.json','application/json');toast('Cópia de segurança preparada.');break;}
case 'restore':{const file=$('#backupfile').files[0];if(!file)throw Error('Selecione um backup.');if(file.size>20_000_000)throw Error('Use um arquivo de até 20 MB.');const backup=JSON.parse(await file.text());if(confirm('Substituir todos os dados locais por este backup? Uma cópia do banco atual será preservada.')){await api('restore',{backup});await refresh('Backup restaurado.')}break;}
case 'export':exportCSV();break;
case 'print':printHTML('<h1>'+esc(titles[route])+'</h1><p>'+esc(S.settings.company)+' · '+datefmt(today())+'</p>'+$('#content').innerHTML,titles[route]);break;
case 'filters':dateFrom=$('#from').value;dateTo=$('#to').value;if(dateFrom&&dateTo&&dateFrom>dateTo)throw Error('A data inicial deve ser anterior à final.');render();break;
case 'period':{dateTo=today();if(a==='all'){dateFrom='';dateTo=''}else{const d=new Date();d.setDate(d.getDate()-Math.max(0,Number(a)-1));dateFrom=d.toLocaleDateString('sv-SE')}render();break;}
case 'stock':stockForm(a);break;
case 'category':categoryFilter=a;render();break;
case 'addcart':addCart(a);break;
case 'catalogadd':{const p=find('products',a);if(p.trackStock&&p.type!=='Serviço'&&p.stock<=p.reserved)throw Error('Produto indisponível no catálogo.');addCart(a);toast('Produto selecionado.');break;}
case 'catalogcheckout':if(!cart.length)throw Error('Selecione produtos primeiro.');if(cartSubtotal()<Math.round((S.settings.minOrder||0)*100))throw Error('Pedido mínimo: '+money(Math.round(S.settings.minOrder*100)));nav('order');break;
case 'cartminus':{const i=cart[Number(a)];i.qty-=find('products',i.productId)?.fractional?0.1:1;i.qty=Math.round(i.qty*1e6)/1e6;if(i.qty<=0)cart.splice(Number(a),1);cartSave();render();break;}
case 'cartplus':{const i=cart[Number(a)];cartAdd(i.productId,find('products',i.productId)?.fractional?0.1:1,i.variant);render();break;}
case 'cartremove':cart.splice(Number(a),1);cartSave();render();break;
case 'clearcart':cart=[];cartSave();render();break;
case 'checkout':if(S.settings.requireCash&&!R('cash').some(c=>c.status==='Aberto')){toast('Abra o caixa antes de registrar a venda.');nav('cash');return}checkout();break;
case 'manualcheckout':quoteMode=false;checkout(true);break;
case 'newquote':quoteMode=true;cart=[];cartSave();nav('order');break;
case 'viewmode':viewMode=viewMode==='Lista'?'Kanban':'Lista';render();break;
case 'orderdetail':orderDetail(a);break;
case 'pay':paymentForm(a);break;
case 'status':formModal('Alterar status',[F('status','Status','select',{options:['Aberto','Em preparo','Pronto','Em entrega','Concluído']})],find('orders',a),data=>api('orders/'+a+'/status',data));break;
case 'cancelorder':if(confirm('Cancelar o pedido? O estoque será devolvido e os valores recebidos serão registrados como estorno.')){await api('orders/'+a+'/cancel',{});closeModal();await refresh('Pedido cancelado.')}break;
case 'convert':if(confirm('Converter em venda e dar baixa no estoque?')){await api('orders/'+a+'/convert',{});closeModal();nav('orders');await refresh('Orçamento convertido.')}break;
case 'receipt':{const o=find('orders',a);showModal('Recibo #'+o.number,receiptHTML(o)+`<div class="formfoot">${btn('Imprimir / PDF','printreceipt:'+a,'print','primary')}</div>`);break;}
case 'printreceipt':printHTML(receiptHTML(find('orders',a)),'Recibo');break;
case 'entry':entryForm(a);break;
case 'settle':if(confirm('Confirmar este lançamento como pago?')){await api('entries/'+a+'/settle',{date:today()});await refresh('Lançamento liquidado.')}break;
case 'cancelentry':if(confirm('Cancelar este lançamento financeiro?')){await api('entries/'+a+'/cancel',{});await refresh('Lançamento cancelado.')}break;
case 'opencash':formModal('Abrir caixa',[F('name','Nome do caixa'),F('opening','Dinheiro inicial na gaveta (R$)','number',{required:true})],{name:S.settings.cashName||'Caixa principal',opening:0},d=>api('cash/open',d));break;
case 'closecash':{const c=find('cash',a);formModal('Fechar caixa · Esperado: '+money(c.expected),[F('counted','Dinheiro contado (R$)','number',{required:true}),F('notes','Observação','textarea',{wide:true})],{},d=>api('cash/'+a+'/close',d));break;}
case 'newpurchase':purchaseForm();break;
case 'purchaseadd':purchaseAdd();break;
case 'removepurchaserow':el.closest('.panel').remove();break;
case 'receivepurchase':if(confirm('Confirmar recebimento? As quantidades serão adicionadas ao estoque e a despesa ficará a pagar.')){await api('purchases/'+a+'/receive',{});await refresh('Produtos recebidos no estoque.')}break;
case 'cancelpurchase':if(confirm('Cancelar este pedido de compra?')){await api('purchases/'+a+'/cancel',{});await refresh('Pedido cancelado.')}break;
case 'purchasedetail':{const p=find('purchases',a);showModal('Pedido ao fornecedor',`<p>${esc(name('suppliers',p.supplierId))} · ${datefmt(p.date)}</p>${table(['Produto','Variação','Qtd.','Custo unitário'],p.items.map(i=>[esc(i.name),esc(i.variant),qty(i.qty),money(i.cost)]))}<div class="totalrow"><span>Total</span><b>${money(p.total)}</b></div><p>${esc(p.notes||'')}</p>`);break;}
case 'paypurchase':formModal('Pagamento ao fornecedor',[F('methodId','Forma de pagamento','ref',{ref:'paymentMethods',required:true})],{methodId:(R('paymentMethods').find(m=>m.name==='Dinheiro')||R('paymentMethods')[0])?.id},d=>api('purchase-payment',{...d,entryId:a}));break;
case 'tablemode':await api('settings',{tableMode:a});await refresh();break;
case 'tableorder':{selectedTableId=a;appendOrderId='';cart=[];cartSave();nav('order');quoteMode=false;toast('Selecione os produtos para '+name('tables',a)+'.');break;}
case 'appendorder':closeModal();appendOrderId=a;cart=[];cartSave();nav('order');toast('Selecione os novos itens para o pedido.');break;
case 'labeladd':labelSelection[a]=(labelSelection[a]||0)+1;render();break;
case 'labelpreview':labelPrice=$('[name=labelPrice]').checked;labelBarcode=$('[name=labelBarcode]').checked;labelColumns=Number($('[name=labelColumns]').value);showModal('Pré-visualização das etiquetas',labelsHTML()+`<div class="formfoot">${btn('Imprimir / PDF','printlabels','print','primary')}</div>`);break;
case 'printlabels':printHTML(labelsHTML(),'Etiquetas');break;
case 'birthdays':{const month=new Date().getMonth()+1;showModal('Aniversariantes do mês',table(['Cliente','Aniversário','Celular'],R('clients').filter(c=>Number(c.birthday?.slice(5,7))===month).map(c=>[esc(c.name),datefmt(c.birthday),esc(c.phone)])));break;}
case 'charge':{const o=find('orders',a),text=(S.settings.chargeMessage||'Olá, {cliente}! Saldo pendente: {valor}. Pedido {pedido}.').replaceAll('{cliente}',name('clients',o.clientId)).replaceAll('{valor}',money(o.total-o.paid)).replaceAll('{pedido}','#'+o.number);showModal('Mensagem de cobrança',`${fieldHTML(F('chargetext','Mensagem','textarea',{wide:true}),{chargetext:text})}<div class="formfoot">${btn('Copiar mensagem','copycharge','file','primary')}</div>`);break;}
case 'copycharge':try{await navigator.clipboard.writeText($('[name=chargetext]').value);toast('Mensagem copiada.')}catch{throw Error('Selecione e copie o texto da mensagem.')}break;
case 'alerts':{const lows=R('products').filter(p=>p.trackStock&&p.type!=='Serviço'&&p.stock<=p.minStock);showModal('Avisos da loja',table(['Produto','Estoque','Mínimo'],lows.map(p=>[esc(p.name),qty(p.stock),qty(p.minStock)])));break;}
}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();try{await handleAction(el.dataset.action,el)}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;const start=e.target.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(start,start)}if(e.target.dataset.labelqty){const n=Number(e.target.value);labelSelection[e.target.dataset.labelqty]=Number.isInteger(n)&&n>=0?n:0;}});
document.addEventListener('change',e=>{if(e.target.id==='statusfilter'){statusFilter=e.target.value;render();}});
document.addEventListener('keydown',e=>{if(e.target.id==='search'&&e.key==='Enter'&&route==='order'){const p=R('products').find(p=>p.barcode&&p.barcode===search.trim());if(p){e.preventDefault();try{addCart(p.id);search='';render()}catch(err){toast(err.message)}}return}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('#modal').open||e.ctrlKey||e.altKey||e.metaKey)return;const shortcuts={v:'order',r:'manual',e:'stock',c:'financial',f:'debts'};if(shortcuts[e.key.toLowerCase()]){e.preventDefault();nav(shortcuts[e.key.toLowerCase()])}});
function onRoute(){let next=location.hash.slice(1)||'home';if(next==='expenses'){location.replace('#financial');return;}if(next!==route){window.scrollTo(0,0);search='';statusFilter='';categoryFilter='';if(next!=='order'){quoteMode=false;appendOrderId='';selectedTableId='';}}if(next!==route){const group=menu.find(([g,links])=>g!=='MEU NEGÓCIO'&&links.some(([id])=>id===next));if(group){menuOpen[group[0]]=true;saveMenuState();}}route=next;render();}
window.addEventListener('hashchange',onRoute);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
load().then(onRoute).catch(err=>{$('#app').innerHTML=`<div class="errorpage"><h1>Não foi possível conectar à Lojinha</h1><p>${esc(err.message)}</p><p>Abra iniciar.bat na pasta do projeto e atualize esta página.</p></div>`});
